/* GENERATED by tools/split-map.js from film-engine/src/index.html: the functions only the dashboard page uses. Do not edit; edit the source or the tool. */


    /**
     * Paint the panels into the home page.
     *
     * Deliberately AFTER the rest of home has rendered and not awaited by it:
     * nine endpoints answering in series is slower than the one /home call, and
     * blocking the greeting on them would make the whole page feel like the
     * slowest report. A panel that cannot load says so — nine silent empties
     * would read as "nothing to report", which is a different claim.
     */
    async function loadHomePanels() {
        const grid = document.getElementById('homePanels');
        if (!grid || !state.currentProject) return;
        grid.innerHTML = '<div class="text-muted">Loading…</div>';

        /*
         * Fetched CONCURRENTLY, unlike the generation paths.
         *
         * The sequential rule elsewhere exists because several generations at
         * one provider is how a queue earns a 429 and the retry costs more than
         * the wait. These are nine local reads against SQLite: in series they
         * measured 8.9s before the block filled, which on the page you land on
         * reads as the app being slow to start. Concurrently it is the slowest
         * one.
         */
        const results = await Promise.all(HOME_PANELS.map(panel =>
            api(`/projects/${state.currentProject.id}/${panel.id}`)
                .then(data => ({ panel, body: esc(panel.render(data)), ok: true }))
                // A panel that cannot load says so. Nine silent empties would
                // read as "nothing to report", which is a different claim.
                .catch(err => ({ panel, body: esc(err.message || 'unavailable'), ok: false }))));

        grid.innerHTML = results.map(({ panel, body, ok }) => `<div class="card home-panel" onclick="navigateTo('${panel.go}')" title="Open ${esc(panel.go)}">
                <div class="flex-between"><strong>${esc(panel.title)}</strong>
                <button class="btn btn-sm" onclick="event.stopPropagation();navigateTo('${panel.go}')">Open</button></div>
                <p class="text-sm ${ok ? '' : 'text-muted'}" style="margin-top:6px;">${body}</p>
            </div>`).join('');
    }

    // ══════════════════════════════════════════════════════════════
    // DASHBOARD
    // ══════════════════════════════════════════════════════════════

    /**
     * The home page: what was I doing, what needs me, where is the film, what is
     * running.
     *
     * Every block reads `home.<field>` from one payload. The dashboard this
     * replaces fetched four endpoints and rendered counts — a summary, which
     * leaves the reader to work out the next action and then find the page it
     * lives on. Each block here carries its own way in.
     */
    async function loadDashboard() {
        if (!state.currentProject) return;
        let home;
        try {
            home = await api('/projects/' + state.currentProject.id + '/home');
        } catch (err) {
            setStatus('Could not load home: ' + err.message);
            return;
        }

        document.getElementById('homeGreeting').innerHTML = homeGreetingHtml(home.greeting);
        document.getElementById('homeResume').innerHTML = homeResumeHtml(home.resume);
        document.getElementById('homeNeeds').innerHTML = homeNeedsHtml(home.needs);
        document.getElementById('homePhases').innerHTML = homePhasesHtml(home.phases);
        document.getElementById('homeActivity').innerHTML = homeActivityHtml(home.activity);
        document.getElementById('homeRunning').innerHTML = homeRunningHtml(home.running);
        setStatus(`${home.greeting.project_title} \u00b7 ${home.greeting.shot_count} shots`);
        loadHomePanels();
    }

    function homeGreetingHtml(g) {
        if (!g) return '';
        // The name is the app author, the one place a name is recorded. Without
        // one the greeting still works — it just does not pretend to know you.
        const who = g.name ? `${esc(g.salutation)}, ${esc(g.name)}` : esc(g.salutation);
        const bits = [esc(g.project_title),
            `${g.shot_count} shot${g.shot_count === 1 ? '' : 's'} across ${g.scene_count} scene${g.scene_count === 1 ? '' : 's'}`];
        if (g.last_opened) bits.push(`last opened ${esc(g.last_opened)}`);
        return `<h1>${who}</h1><p>${bits.join(' &middot; ')}</p>`;
    }

    function homeResumeHtml(r) {
        if (!r) return '<div class="k">Pick up where you left off</div><div class="home-empty">Nothing worked on yet.</div>';
        const src = r.has_keyframe && state.currentProject
            ? `${API_BASE}/film/storyboards/${state.currentProject.id}/${encodeURIComponent(r.shot_code)}.png`
            : '';
        return `<div class="k">Pick up where you left off</div>
            <div class="home-resume-body home-resume">
                ${src ? `<img class="home-thumb" src="${src}" onerror="this.style.visibility='hidden'">`
                      : '<div class="home-thumb"></div>'}
                <div style="flex:1;min-width:0;">
                    <h3>${esc(r.headline)}</h3>
                    <p class="text-sm text-muted" style="margin:0 0 12px;line-height:1.5;">${esc(r.summary)}</p>
                    <p class="text-sm text-muted" style="margin:0 0 12px;">${esc(r.state)}${r.when ? ' &middot; ' + esc(r.when) : ''}</p>
                    <button class="btn btn-primary btn-sm" onclick="resumeShot('${r.shot_id}')">Resume</button>
                    <button class="btn btn-secondary btn-sm" onclick="navigateTo('storyboard')">Open board</button>
                </div>
            </div>`;
    }

    function homeNeedsHtml(items) {
        if (!items || !items.length) {
            return '<div class="k">Needs you</div><div class="home-empty">Nothing is blocking the film.</div>';
        }
        // Every line carries the page that fixes it. An item that names a
        // problem and not its destination is a to-do list that makes you go and
        // find the page yourself.
        return '<div class="k">Needs you</div>' + items.map(n =>
            `<div class="home-need"><span class="dot"></span><span>${esc(n.label)}</span>
             <a href="#" onclick="event.preventDefault();navigateTo('${n.page}')">${esc(capitalise(n.phase || 'Open'))}</a></div>`).join('');
    }

    function capitalise(s) { return String(s || '').charAt(0).toUpperCase() + String(s || '').slice(1); }

    function homePhasesHtml(phases) {
        return (phases || []).map(p => {
            const pct = p.of > 0 ? Math.round((p.done / p.of) * 100) : 0;
            return `<button class="home-phase" onclick="navigateTo('${p.page}')">
                <div class="row"><span class="name">${esc(p.label)}</span>
                    <span class="frac">${p.done}/${p.of}</span></div>
                <div class="bar"><div class="fill" style="width:${pct}%;"></div></div>
                <div class="note">${esc(p.note)}</div>
            </button>`;
        }).join('');
    }

    function homeActivityHtml(items) {
        if (!items || !items.length) {
            return '<div class="k">Recent activity</div><div class="home-empty">Nothing generated yet.</div>';
        }
        return '<div class="k">Recent activity</div>' + items.map(a =>
            `<div class="home-line"><span class="t">${esc(String(a.when || ''))}</span><span>${esc(a.what)}</span></div>`).join('');
    }

    function homeRunningHtml(jobs) {
        if (!jobs || !jobs.length) {
            // Empty is a real answer here, not a missing one.
            return '<div class="k">Running now</div><div class="home-empty">Nothing is generating.</div>'
                + '<a href="#" style="color:#6690ff;font-size:12.5px;" onclick="event.preventDefault();navigateTo(\'jobsqueue\')">Open job queue &rarr;</a>';
        }
        return '<div class="k">Running now</div>' + jobs.map(j =>
            `<div class="home-run"><div class="row"><span>${esc(j.kind)}${j.shot_code ? ' &mdash; ' + esc(j.shot_code) : ''}</span>
             <span class="text-muted text-sm">${esc(j.status)}</span></div>
             <div class="bar"><div class="fill" style="width:${j.status === 'running' ? 60 : 15}%;"></div></div></div>`).join('')
            + '<a href="#" style="color:#6690ff;font-size:12.5px;" onclick="event.preventDefault();navigateTo(\'jobsqueue\')">Open job queue &rarr;</a>';
    }

    /**
     * Pick up where you left off: go to the board AND open the frame.
     *
     * Both halves matter. Opening the viewer alone leaves you back on the home
     * page when you close it, which is not where you were working; navigating
     * alone makes Resume identical to Open shot.
     */
    async function resumeShot(shotId) {
        navigateTo('storyboard');
        await openFrameViewer(shotId);
    }
